const refundCampaignInvestments = `-- name: RefundCampaignInvestments :exec
UPDATE investments
SET status = 'refunded'
WHERE campaign_id = $1 AND status = 'confirmed'
`

func (q *Queries) RefundCampaignInvestments(ctx context.Context, campaignID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, refundCampaignInvestments, campaignID)
	return err
}

